import { randomBytes, createHash, timingSafeEqual } from "node:crypto";

/**
 * Generates a high-entropy, URL-safe opaque token (refresh tokens,
 * email-verification/password-reset/OTP tokens, recovery codes all use
 * this — never a JWT, since these are meant to be single-purpose, easily
 * revocable-by-deleting-the-row values, not self-contained claims).
 */
export function generateOpaqueToken(byteLength = 32): string {
  return randomBytes(byteLength).toString("base64url");
}

/**
 * Fast, deterministic hash for lookup — appropriate for opaque tokens
 * (already high-entropy, generated by us, single-use, short-lived), unlike
 * passwords or TOTP secrets which need argon2/encryption respectively.
 * See docs/authentication.md § "Why not argon2 for every secret" for the
 * full reasoning.
 */
export function hashOpaqueToken(token: string): string {
  return createHash("sha256").update(token).digest("hex");
}

/** Constant-time comparison for anywhere a raw (non-hashed) secret is compared directly. */
export function safeCompare(a: string, b: string): boolean {
  const bufA = Buffer.from(a);
  const bufB = Buffer.from(b);
  if (bufA.length !== bufB.length) return false;
  return timingSafeEqual(bufA, bufB);
}
